$('.show_confirm').click(function (event) {
    const form = $(this).closest("form");
    event.preventDefault();

    swal.fire({
        title: "के तपाइँ मेटाउन निश्चित हुनुहुन्छ ?",
        text: "यदि तपाईंले यसलाई मेटाउनुभयो भने, यो सदाको लागि हट्नेछ।",
        icon: "warning",
        showCancelButton: true,
        confirmButtonColor: 'red',
        confirmButtonText: "Delete",
        dangerMode: true,

    })
        .then((willDelete) => {
            if (willDelete.isConfirmed) {
                form.submit();
            }
        });
});

window.addEventListener('alert_message', event => {
    swal.fire({
        title: event.detail.title,
        text: event.detail.text,
        icon: event.detail.type,
    });
});
window.addEventListener('toast_message', event => {
    swal.fire({
        title: event.detail.title,
        toast: true,
        position: 'top-right',
        showConfirmButton: false,
        width: 400,
        timer: 3000,
        timerProgressBar: true,
        icon: event.detail.type,
    });
});

$(document).ready(function () {
    $('.filter-form').focusout(function () {
        $(this).closest('form').submit();
    });
});

$('.confirm_pin').click(function (event) {
    event.preventDefault();
    swal.fire({
        title: 'प्रविष्ट कोड',
        input: 'password',
        inputAttributes: {
            autocapitalize: 'off'
        },
        showCancelButton: true,
        cancelButtonText: 'रद्द गर्नुहोस्',
        confirmButtonText: 'पेश गर्नुहोस्',
        showLoaderOnConfirm: true,
        preConfirm: (pin) => {
            return new Promise((resolve, reject) => {
                $.ajaxSetup({
                    headers: {
                        'X-CSRF-TOKEN': $('meta[name="csrf-token"]').attr('content')
                    }
                });
                $.ajax({
                    url: validationUrl,
                    type: 'POST',
                    data: {pin: pin},
                    success: function (response) {
                        console.log(response, response.valid);
                        if (response == true) {
                            resolve();
                        } else {
                            invalidPin()
                        }
                    },
                    error: function () {
                        invalidPin()
                    }
                });
            });
        },
        allowOutsideClick: () => !swal.isLoading()
    }).then((result) => {
        console.log(result, result.value);
        if (result.value) {
            // get value in data bs type
            var type = $(this).data('bs-type');
            // check if type is delete then delete the record and if edit is then redirect to edit page
            if (type == 'delete') {
                $(this).closest('form').submit();
            } else if (type == 'edit') {
                // get href value
                var href = $(this).attr('href');
                window.location.href = href;
            }
        }
});
});

function invalidPin() {
    let timerInterval
    Swal.fire({
        title: 'पुन: प्रयास गर्नुहोस्',
        html: 'कृपया मान्य कोड प्रविष्ट गर्नुहोस्',
        timer: 2000,
        timerProgressBar: true,

        willClose: () => {
            clearInterval(timerInterval)
        }
    })
}
